function log(text){state.logs.unshift(text);state.logs=state.logs.slice(0,8);$('#battleLog').innerHTML=state.logs.map(x=>`<div>✦ ${x}</div>`).join('')}
function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),1900)}
function showFloat(text,who='enemy'){const el=document.createElement('span');el.className=`float-text ${who}`;el.textContent=text;$('#fxLayer').appendChild(el);setTimeout(()=>el.remove(),950)}
function shuffle(a){for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function startBattle(){state.enemy=enemies[Math.min(state.floor-1,enemies.length-1)];state.enemyMax=state.enemy.hp;state.enemyHp=state.enemy.hp;state.round=1;state.guard=0;state.poison=0;state.enemyWeaken=0;state.ally=state.caught>0;state.turn=true;state.ended=false;state.draw=shuffle([...state.deck]);state.discard=[];state.hand=[];state.energy=state.maxEnergy;drawCards(5);state.logs=[];log(`A wild ${state.enemy.name} appears.`);$('#battleTitle').textContent=state.enemy.name+' approaches';$('#phaseLabel').innerHTML=`WILD ENCOUNTER <span>•</span> FLOOR ${String(state.floor).padStart(2,'0')}`;$('#sceneCaption').textContent=state.enemy.caption;$('#roundNum').textContent=state.round;render();}
function drawCards(n){for(let i=0;i<n;i++){if(!state.draw.length){if(!state.discard.length)break;state.draw=shuffle(state.discard.splice(0))}state.hand.push(state.draw.pop())}}
function render(){const hpPct=Math.max(0,state.hp/state.maxHp*100),enemyPct=Math.max(0,state.enemyHp/state.enemyMax*100);$('#hpText').textContent=`${state.hp} / ${state.maxHp}`;$('#hpBar').style.width=hpPct+'%';$('#focusText').textContent=`${state.energy} / ${state.maxEnergy}`;$('#focusBar').style.width=(state.energy/state.maxEnergy*100)+'%';$('#goldText').textContent=state.gold;$('#orbText').textContent=state.orbs;$('#creatureCount').textContent=state.caught;$('#deckCount').textContent=state.deck.length;$('#enemyName').textContent=state.enemy.name;$('#enemyType').textContent=state.enemy.type;$('#enemyHpText').textContent=`${Math.max(0,state.enemyHp)} / ${state.enemyMax}`;$('#enemyHpBar').style.width=enemyPct+'%';$('#enemyHpBar').style.background=enemyPct<35?'linear-gradient(90deg,#d97782,#f5ab89)':'linear-gradient(90deg,#ee8876,#f3bd82)';$('#intentText').textContent=state.enemyIntent===0?'Gathering strength':state.enemy.intent;$('#intentValue').textContent=state.enemyIntent||'—';$('#intentIcon').textContent=state.enemyIntent===0?'✦':'⚔';$('#roundNum').textContent=state.round;$('#energyText').textContent=`${state.energy} / ${state.maxEnergy}`;$('#energyDots').innerHTML=Array.from({length:state.maxEnergy},(_,i)=>`<i class="energy-dot ${i<state.energy?'full':''}"></i>`).join('');$('#drawCount').textContent=state.draw.length;$('#discardCount').textContent=state.discard.length;$('#mobileHp').textContent=state.hp;$('#mobileEnergy').textContent=state.energy;$('#handSubtitle').textContent=state.turn?'Choose your moves':(state.ended?'Encounter complete':'Enemy turn');$('#combatMessage').textContent=state.ended?'Victory · the wilds offer a reward':state.turn?'Your turn · play cards to shape the fight':`The ${state.enemy.name} is moving…`;
 const catchBtn=$('#catchBtn');catchBtn.disabled=!state.turn||state.ended||state.orbs<=0||state.enemyHp/state.enemyMax>.35;catchBtn.title=state.orbs<=0?'No capture orbs left':state.enemyHp/state.enemyMax>.35?'Weaken it below 35% health first':'Throw a capture orb';$('#hand').innerHTML=state.hand.length?state.hand.map((id,i)=>{const c=cards[id];const disabled=!state.turn||state.ended||state.energy<c.cost;return `<article class="card ${disabled?'disabled':''}" style="--accent:${c.tone}" data-index="${i}" role="button" tabindex="0" aria-label="${c.name}, costs ${c.cost}. ${c.desc.replace(/<[^>]*>/g,'')}"><div class="card-top"><span class="energy-cost">${c.cost}</span><span class="card-rarity">${id==='beast'?'BOND':'BASIC'}</span></div><div class="card-art">${c.icon}</div><div class="card-title">${c.name}</div><div class="card-desc">${c.desc}</div></article>`}).join(''):'<div class="empty-hand">No cards in hand. End your turn to draw again.</div>';$('#hand').querySelectorAll('.card').forEach(el=>{el.addEventListener('click',()=>playCard(+el.dataset.index));el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();playCard(+el.dataset.index)}})});}
function damageEnemy(n){const dealt=Math.max(0,n);state.enemyHp=Math.max(0,state.enemyHp-dealt);showFloat(`−${dealt}`,'enemy');log(`You deal ${dealt} damage.`);if(state.enemyHp<=0){victory();return true}return false}
function playCard(i){if(!state.turn||state.ended)return;const id=state.hand[i],c=cards[id];if(!c||state.energy<c.cost)return toast('Not enough focus');state.energy-=c.cost;state.hand.splice(i,1);state.discard.push(id);log(`Played ${c.name}.`);
 if(c.kind==='attack'){if(damageEnemy(c.value))return;if(id==='volley')drawCards(1);if(id==='beast'){state.ally=true;toast('Your Wildkin joins the fight!')}}
 if(c.kind==='block'){state.guard+=c.value;toast(`+${c.value} guard`);if(id==='thorn'&&state.enemyHp>0){if(damageEnemy(3))return}}
 if(c.kind==='focus'){state.energy=Math.min(state.maxEnergy+1,state.energy+1);toast('Focus gathered')}
 if(c.kind==='heal'){const healed=Math.min(state.maxHp-state.hp,c.value);state.hp+=healed;showFloat(`+${healed}`,'heal');toast(`Restored ${healed} vitality`)}
 if(c.kind==='weaken'){if(damageEnemy(c.value+3))return;state.enemyWeaken+=c.value;toast('The next strike is weakened')}
 render();}
function endTurn(){if(!state.turn||state.ended)return;state.turn=false;state.discard.push(...state.hand);state.hand=[];render();setTimeout(()=>{if(state.ended)return;if(state.poison>0){state.enemyHp=Math.max(0,state.enemyHp-state.poison);showFloat(`−${state.poison}`,'enemy');log(`Wildkin poison deals ${state.poison}.`);if(state.enemyHp<=0){victory();return}}
 if(state.enemyIntent===0){state.enemyIntent=state.enemy.damage+Math.floor(state.round/3)}else{let hit=Math.max(0,state.enemyIntent-state.guard-state.enemyWeaken);state.guard=Math.max(0,state.guard-state.enemyIntent);state.enemyWeaken=0;if(hit>0){state.hp=Math.max(0,state.hp-hit);showFloat(`−${hit}`,'player');log(`${state.enemy.name} strikes for ${hit}.`)}else log('Your guard absorbs the strike.');if(state.hp<=0){defeat();return}state.enemyIntent=state.round%3===0?0:state.enemy.damage+Math.floor(state.round/3)}
 state.round++;state.energy=state.maxEnergy;state.turn=true;drawCards(5);render();},450)}
function attemptCatch(){if($('#catchBtn').disabled)return;if(state.orbs<=0)return toast('You are out of capture orbs');state.orbs--;const ratio=state.enemyHp/state.enemyMax;const chance=Math.min(.96,.48+(1-ratio)*.65);const roll=Math.random();log(`You throw a capture orb…`);if(roll<chance){state.caught++;state.deck.push('beast');state.enemyHp=0;state.ended=true;render();showFloat('CAUGHT!','enemy');log(`${state.enemy.name} joins your expedition!`);$('#sceneCaption').textContent=`${state.enemy.name} is now your companion!`;toast(`${state.enemy.name} was caught! A Wildkin Bond card was added.`);setTimeout(victory,true?350:350);return}showFloat('ESCAPED!','enemy');toast('It broke free!');log(`${state.enemy.name} broke free.`);render();endTurn()}
function victory(){if(state.ended&&state.enemyHp>0)return;state.ended=true;state.enemyHp=0;render();$('#sceneCaption').textContent=`${state.enemy.name} retreats into the mist.`;setTimeout(()=>showReward(),500)}
function defeat(){state.ended=true;render();modal('The trail ends here','Your vitality has faded in the Verdant Reach.','',`<button class="modal-btn primary" id="restartBtn">BEGIN A NEW EXPEDITION</button>`);$('#restartBtn').onclick=resetRun}
function modal(title,desc,content='',actions=''){const root=$('#modalRoot');root.innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="modal-kicker">✦ MYTHBOUND · WILDS OF AETHER</div><h2>${title}</h2><p>${desc}</p>${content}${actions?`<div class="modal-actions">${actions}</div>`:''}</div></div>`;root.querySelector('.modal-backdrop').addEventListener('click',e=>{if(e.target===e.currentTarget&&root.dataset.dismiss==='yes')root.innerHTML=''})}
function showReward(){if(state.floor>=8){modal('The Reach is restored','The Gloamstag bows its antlers. You have brought peace to the Verdant Reach.','',`<button class="modal-btn primary" id="restartBtn">PLAY AGAIN</button>`);$('#restartBtn').onclick=resetRun;return}const picks=shuffle(['spark','snare','volley','thorn','flare','mend','guard']).slice(0,3);let content=`<div class="reward-grid"><button class="reward-option" id="rewardGold"><span class="reward-icon">◈</span><span><strong>Find 24 shards</strong><small>Supplies for the road.</small></span></button><button class="reward-option" id="rewardHeal"><span class="reward-icon">❀</span><span><strong>Rest and recover</strong><small>Restore 18 vitality.</small></span></button></div><h3 style="font:500 10px var(--mono);letter-spacing:1px;color:#aab6c2;margin:20px 0 0">OR ADD A CARD TO YOUR DECK</h3><div class="reward-grid">${picks.map((id,i)=>`<button class="reward-option add-card" data-card="${id}"><span class="reward-icon" style="color:${cards[id].tone}">${cards[id].icon}</span><span><strong>${cards[id].name}</strong><small>${cards[id].desc.replace(/<[^>]*>/g,'')}</small></span></button>`).join('')}</div>`;modal(`Victory at floor ${state.floor}`,`The ${state.enemy.name} yields. Choose a reward before moving on.`,content);$('#rewardGold').onclick=()=>afterReward(()=>state.gold+=24);$('#rewardHeal').onclick=()=>afterReward(()=>state.hp=Math.min(state.maxHp,state.hp+18));document.querySelectorAll('.add-card').forEach(b=>b.onclick=()=>afterReward(()=>state.deck.push(b.dataset.card)));}
function afterReward(fn){fn();$('#modalRoot').innerHTML='';state.floor++;render();showPath()}
function showPath(){const choices=[{name:'Whispering Grove',icon:'⌂',copy:'A quiet place to recover 16 vitality.',act:()=>{state.hp=Math.min(state.maxHp,state.hp+16);toast('You rested beneath the old trees.')}},{name:'Wayfarer’s Cache',icon:'◇',copy:'A hidden cache holds 18 shards and a capture orb.',act:()=>{state.gold+=18;state.orbs++;toast('You found supplies in the cache.')}},{name:'Wild Crossing',icon:'⚔',copy:'Face another wildkin for extra rewards.',act:()=>{state.gold+=10;toast('The crossing is rich with shards.')}}];const final=state.floor>=8;const chosen=shuffle(choices).slice(0,2);const content=final?'<div class="choice-node"><h3>Guardian’s Hollow</h3><p>The Gloamstag waits at the heart of the forest.</p><button id="goBattle">ENTER THE HOLLOW →</button></div>':chosen.map((x,i)=>`<div class="choice-node"><h3>${x.icon} ${x.name}</h3><p>${x.copy}</p><button data-path="${i}">TAKE THIS PATH →</button></div>`).join('');modal(final?'The Guardian stirs':'Choose your path',final?'The forest grows still. A powerful presence watches from the hollow.':'The trail forks ahead. Where will your expedition lead?',content);if(final)$('#goBattle').onclick=()=>{state.floor=8;$('#modalRoot').innerHTML='';startBattle()};else document.querySelectorAll('[data-path]').forEach((b,i)=>b.onclick=()=>{chosen[i].act();$('#modalRoot').innerHTML='';startBattle()})}
function resetRun(){Object.assign(state,{hp:72,maxHp:72,energy:3,maxEnergy:3,guard:0,gold:42,orbs:1,floor:1,round:1,deck:['strike','strike','strike','quick','quick','guard','guard','guard','focus','mend'],caught:0,runOver:false});$('#modalRoot').innerHTML='';startBattle()}
function showDeck(){const list=state.deck.map(id=>`<div class="deck-entry"><strong>${cards[id].name}</strong><span>${cards[id].cost} ✦</span></div>`).join('');modal(`Expedition deck · ${state.deck.length} cards`,'Your cards return to the draw pile after each turn.',`<div class="modal-card-list">${list}</div>`,`<button class="modal-btn primary" id="closeModal">CLOSE</button>`);$('#closeModal').onclick=()=>$('#modalRoot').innerHTML=''}
function showHelp(){modal('How to play','Build a deck, outsmart wildkin, and invite the ones you catch to fight by your side.','<div class="choice-node"><h3>✦ Play cards</h3><p>Cards cost focus. Attacks deal damage, guard blocks the next hit, and healing restores vitality. End your turn to draw a fresh hand.</p></div><div class="choice-node"><h3>◉ Catch wildkin</h3><p>Bring a wildkin below 35% health, then throw an orb. A successful catch adds a Wildkin Bond card to your deck. Lower health means better odds.</p></div><div class="choice-node"><h3>◇ Make it to floor 8</h3><p>Choose rewards and paths between encounters. Rest when you need to. Defeat the guardian to complete your expedition.</p></div>','<button class="modal-btn primary" id="closeModal">GOT IT</button>');$('#closeModal').onclick=()=>$('#modalRoot').innerHTML=''}
$('#endTurnBtn').onclick=endTurn;$('#mobileEnd').onclick=endTurn;$('#catchBtn').onclick=attemptCatch;$('#deckBtn').onclick=showDeck;$('#helpBtn').onclick=showHelp;$('#discardBtn').onclick=()=>toast(`Discard pile · ${state.discard.length} cards`);$('#logBtn').onclick=()=>$('#battleLog').classList.toggle('open');document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.tagName!=='BUTTON'&&state.turn)endTurn();if(e.key==='1')attemptCatch()});
// Hand-painted, perspective 3D-style forest arena rendered in Canvas for a lightweight mobile experience.
const canvas=$('#scene'),ctx=canvas.getContext('2d');let W=0,H=0,dpr=1,tick=0,particles=[];
function resize(){const r=canvas.getBoundingClientRect();dpr=Math.min(window.devicePixelRatio||1,2);W=r.width;H=r.height;canvas.width=Math.floor(W*dpr);canvas.height=Math.floor(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);particles=Array.from({length:38},()=>({x:Math.random()*W,y:Math.random()*H*.8,r:Math.random()*1.8+.4,s:Math.random()*.3+.08,a:Math.random()*.5+.15}))}
function ellipse(x,y,rx,ry,fill){ctx.fillStyle=fill;ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fill()}
function drawTree(x,y,s,color){ctx.save();ctx.translate(x,y);ctx.scale(s,s);ctx.fillStyle='#182a2d';ctx.beginPath();ctx.moveTo(-5,5);ctx.lineTo(-2,-95);ctx.lineTo(3,-100);ctx.lineTo(7,5);ctx.fill();for(let i=0;i<4;i++){const yy=-28-i*19;ctx.fillStyle=i%2?color:'#314a43';ctx.beginPath();ctx.moveTo(-31+i*3,yy+22);ctx.quadraticCurveTo(-25,yy-14,0,yy-27);ctx.quadraticCurveTo(22,yy-11,31-i*3,yy+22);ctx.quadraticCurveTo(0,yy+12,-31+i*3,yy+22);ctx.fill()}ctx.restore()}
function drawScene(){if(!W||!H)return;tick+=.012;const h=H,w=W;const sky=ctx.createLinearGradient(0,0,0,h);sky.addColorStop(0,'#1c3440');sky.addColorStop(.4,'#586e68');sky.addColorStop(.72,'#3b544b');sky.addColorStop(1,'#1b2b30');ctx.fillStyle=sky;ctx.fillRect(0,0,w,h);
 // distant foggy ridges
 for(let j=0;j<3;j++){ctx.beginPath();const y=h*(.40+j*.055);ctx.moveTo(0,y);for(let x=0;x<=w+10;x+=12)ctx.lineTo(x,y+Math.sin(x*.012+j*2)*9+Math.cos(x*.023+j)*5);ctx.lineTo(w,h*.74);ctx.lineTo(0,h*.74);ctx.closePath();ctx.fillStyle=['#62786c55','#344e495e','#263d3d9c'][j];ctx.fill()}
 // atmospheric light shafts
 ctx.save();ctx.globalAlpha=.12;for(let i=0;i<5;i++){ctx.beginPath();ctx.moveTo(w*(.36+i*.05),0);ctx.lineTo(w*(.54+i*.08),h*.68);ctx.lineTo(w*(.50+i*.035),h*.68);ctx.closePath();ctx.fillStyle='#d8d3a6';ctx.fill()}ctx.restore();
 // ground plane / 3D perspective lines
 const ground=ctx.createLinearGradient(0,h*.57,0,h);ground.addColorStop(0,'#35463d');ground.addColorStop(1,'#172a2c');ctx.fillStyle=ground;ctx.beginPath();ctx.moveTo(0,h*.56);ctx.lineTo(w,h*.56);ctx.lineTo(w,h);ctx.lineTo(0,h);ctx.fill();ctx.strokeStyle='#c8d6a11e';ctx.lineWidth=1;
 for(let i=0;i<9;i++){let y=h*.57+i*i*h*.006;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke()}for(let i=-8;i<=8;i++){ctx.beginPath();ctx.moveTo(w*.5+i*4,h*.56);ctx.lineTo(w*.5+i*w*.14,h);ctx.stroke()}
 // stepping stones and plants
 for(let i=0;i<9;i++){let x=(i*173+tick*8)%(w+70)-25,y=h*(.66+(i%4)*.085),s=.3+(y/h)*.8;ellipse(x,y,13*s,4*s,'#a6ad8d29');ctx.strokeStyle='#b9c29435';ctx.beginPath();ctx.ellipse(x,y,13*s,4*s,0,0,Math.PI*2);ctx.stroke();if(i%2===0){ctx.strokeStyle='#a1b77b99';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x,y);ctx.quadraticCurveTo(x-3*s,y-9*s,x-7*s,y-11*s);ctx.moveTo(x,y);ctx.quadraticCurveTo(x+2*s,y-8*s,x+8*s,y-10*s);ctx.stroke()}}
 // framing trees
 drawTree(w*.05,h*.66,1.3,'#263f3b');drawTree(w*.19,h*.52,.88,'#2d4840');drawTree(w*.79,h*.53,.95,'#304940');drawTree(w*.96,h*.66,1.33,'#223b37');drawTree(w*.31,h*.46,.55,'#405c4c');drawTree(w*.68,h*.45,.58,'#3b5949');
 // glowing forest portal in the middle distance
 const px=w*.5,py=h*.47;ctx.save();ctx.globalAlpha=.3+Math.sin(tick*2)*.04;const glow=ctx.createRadialGradient(px,py,2,px,py,w*.17);glow.addColorStop(0,'#d7e4a866');glow.addColorStop(1,'#a9d8a500');ctx.fillStyle=glow;ctx.fillRect(px-w*.2,py-h*.28,w*.4,h*.54);ctx.restore();
 // floating motes
 particles.forEach(p=>{p.y-=p.s;if(p.y<0)p.y=h*.8;p.x+=Math.sin(tick+p.y)*.14;ctx.globalAlpha=p.a*(.7+Math.sin(tick*3+p.x)*.25);ellipse(p.x,p.y,p.r,p.r,'#d9e8bd');});ctx.globalAlpha=1;
 const e=state.enemy||enemies[0],ex=w*.68,ey=h*.58,scale=Math.min(w/700,h/340); // enemy plinth
 ellipse(ex,ey+22*scale,57*scale,12*scale,'#0b171b88');ctx.save();ctx.translate(ex,ey+12*scale);ctx.rotate(-.05);ctx.fillStyle='#829477';ctx.beginPath();ctx.ellipse(0,0,43*scale,11*scale,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#d7d2a777';ctx.lineWidth=1;ctx.stroke();ctx.restore();
 const aura=ctx.createRadialGradient(ex,ey-23*scale,5,ex,ey-23*scale,56*scale);aura.addColorStop(0,e.color+'66');aura.addColorStop(1,e.color+'00');ctx.fillStyle=aura;ctx.beginPath();ctx.arc(ex,ey-23*scale,56*scale,0,Math.PI*2);ctx.fill();
 // 3D creature stand-in with layered shadow, aura and a friendly companion glyph
 ctx.save();ctx.translate(ex,ey-12*scale+Math.sin(tick*2)*2*scale);ctx.rotate(Math.sin(tick)*.018);ctx.font=`${Math.floor(69*scale)}px "Apple Color Emoji","Segoe UI Emoji",sans-serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.shadowColor=e.color;ctx.shadowBlur=16*scale;ctx.fillText(e.emoji,0,0);ctx.restore();
 // player silhouette and orb light in foreground
 const ax=w*.31,ay=h*.73;ellipse(ax,ay+21*scale,25*scale,6*scale,'#08151899');ctx.fillStyle='#293941';ctx.beginPath();ctx.ellipse(ax,ay+4*scale,13*scale,20*scale,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#dac9a6';ctx.beginPath();ctx.arc(ax,ay-18*scale,9*scale,0,Math.PI*2);ctx.fill();ctx.fillStyle='#786f5c';ctx.beginPath();ctx.moveTo(ax-11*scale,ay-19*scale);ctx.lineTo(ax,ay-32*scale);ctx.lineTo(ax+11*scale,ay-19*scale);ctx.closePath();ctx.fill();ctx.fillStyle='#a6ddbb';ctx.beginPath();ctx.arc(ax+17*scale,ay-7*scale,4*scale+Math.sin(tick*4)*1,0,Math.PI*2);ctx.fill();ctx.shadowColor='#9ce1b6';ctx.shadowBlur=12;ctx.fill();ctx.shadowBlur=0;
 if(state.ally&&state.caught){ctx.globalAlpha=.78;ctx.font=`${Math.floor(24*scale)}px "Apple Color Emoji","Segoe UI Emoji",sans-serif`;ctx.textAlign='center';ctx.fillText('✦',ax+37*scale,ay-18*scale);ctx.globalAlpha=1}
 requestAnimationFrame(drawScene)}
